from __future__ import annotations

import json
import math
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable, Iterator, Sequence


def _load_jsonl(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for line in path.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        rows.append(json.loads(line))
    return rows


@dataclass(frozen=True)
class AffineModeModel:
    b: list[float]  # len 24
    W: list[list[float]]  # 24x6

    def f(self, u: Sequence[float]) -> list[float]:
        if len(u) != 6:
            raise ValueError("u must be length 6")
        out = [0.0] * 24
        for j in range(24):
            s = self.b[j]
            row = self.W[j]
            s += row[0] * u[0]
            s += row[1] * u[1]
            s += row[2] * u[2]
            s += row[3] * u[3]
            s += row[4] * u[4]
            s += row[5] * u[5]
            out[j] = s
        return out


@dataclass(frozen=True)
class BistableModel:
    low: AffineModeModel
    high: AffineModeModel
    theta: float  # switching threshold on sum(u_raw)
    u_lin_clip: float  # clip magnitude for affine response
    tau: float  # ticks
    p_high0: float  # probability fresh draw starts in high basin
    process_noise: float  # extra uncertainty (sensor units)

    def simulate_tail_mean(
        self,
        u_seq: Sequence[Sequence[float]],  # (T,6)
        *,
        init_mode: str,
        tail: int = 20,
    ) -> list[float]:
        T = len(u_seq)
        if T == 0:
            raise ValueError("u_seq is empty")
        if tail <= 0:
            raise ValueError("tail must be positive")

        alpha = 1.0 - math.exp(-1.0 / max(self.tau, 1e-6))
        mode = init_mode
        if mode not in ("low", "high"):
            raise ValueError("init_mode must be 'low' or 'high'")

        y = (self.high.b[:] if mode == "high" else self.low.b[:])
        tail_buf: list[list[float]] = []

        for t in range(T):
            u_raw = u_seq[t]
            if len(u_raw) != 6:
                raise ValueError("u_seq entries must be length 6")
            drive = float(sum(u_raw))
            if drive >= self.theta:
                mode = "high"
            elif drive <= -self.theta:
                mode = "low"

            u = [max(-self.u_lin_clip, min(self.u_lin_clip, float(x))) for x in u_raw]
            target = self.high.f(u) if mode == "high" else self.low.f(u)
            for j in range(24):
                y[j] += alpha * (target[j] - y[j])

            if t >= T - tail:
                tail_buf.append(y[:])

        mean = [0.0] * 24
        denom = float(len(tail_buf))
        for yy in tail_buf:
            for j in range(24):
                mean[j] += yy[j]
        for j in range(24):
            mean[j] /= denom
        return mean

    def predict_tail_mean(
        self, u_seq: Sequence[Sequence[float]], *, tail: int = 20
    ) -> tuple[list[float], list[float]]:
        m_hi = self.simulate_tail_mean(u_seq, init_mode="high", tail=tail)
        m_lo = self.simulate_tail_mean(u_seq, init_mode="low", tail=tail)

        p = self.p_high0
        mean = [p * m_hi[j] + (1.0 - p) * m_lo[j] for j in range(24)]
        # crude uncertainty: mixture spread + additive process noise
        mix = math.sqrt(max(p * (1.0 - p), 0.0))
        sd = [math.sqrt((abs(m_hi[j] - m_lo[j]) * mix) ** 2 + self.process_noise**2) for j in range(24)]
        return mean, sd


def build_from_calibration(
    calibration_path: Path = Path("physim/data/calibration.jsonl"),
    initial_modes_path: Path = Path("physim/data/initial_modes.jsonl"),
    *,
    theta: float = 0.71,
    u_lin_clip: float = 0.6,
    tau: float = 25.0,
    process_noise: float = 0.08,
) -> BistableModel:
    rows = _load_jsonl(calibration_path)

    def get_row(rid: str) -> dict[str, Any]:
        for r in rows:
            if r.get("id") == rid:
                return r
        raise KeyError(f"Missing calibration id={rid!r}")

    a = float(get_row("low_baseline_u0")["a"])

    def mode_model(mode: str) -> AffineModeModel:
        base = [float(get_row(f"{mode}_baseline_u0")["tail_mean"][str(i)]) for i in range(24)]
        W: list[list[float]] = [[0.0] * 6 for _ in range(24)]
        for ui in range(6):
            rp = get_row(f"{mode}_u{ui}_p06")
            rm = get_row(f"{mode}_u{ui}_m06")
            yp = [float(rp["tail_mean"][str(i)]) for i in range(24)]
            ym = [float(rm["tail_mean"][str(i)]) for i in range(24)]
            for j in range(24):
                W[j][ui] = (yp[j] - ym[j]) / (2.0 * a)
        return AffineModeModel(b=base, W=W)

    # Estimate p_high0 from initial mode samples (sensor0 sign).
    init_rows = _load_jsonl(initial_modes_path)
    vals: list[float] = []
    for r in init_rows:
        tm = r.get("tail_mean", {})
        if "0" in tm:
            vals.append(float(tm["0"]))
    if not vals:
        p_high0 = 0.7
    else:
        p_high0 = float(sum(1 for v in vals if v > 0.0) / len(vals))

    return BistableModel(
        low=mode_model("low"),
        high=mode_model("high"),
        theta=theta,
        u_lin_clip=u_lin_clip,
        tau=tau,
        p_high0=p_high0,
        process_noise=process_noise,
    )


def expand_segments(segments: Iterable[dict[str, Any]]) -> list[list[float]]:
    seq: list[list[list[float]]] = []
    for seg in segments:
        t = int(seg["t"])
        if t <= 0:
            continue
        if "u" in seg:
            u = [float(x) for x in seg["u"]]
            if len(u) != 6:
                raise ValueError("segment u must be length 6")
            seq.append([u[:] for _ in range(t)])
        else:
            u0 = [float(x) for x in seg["u_start"]]
            u1 = [float(x) for x in seg["u_end"]]
            if len(u0) != 6 or len(u1) != 6:
                raise ValueError("segment u_start/u_end must be length 6")
            ramp: list[list[float]] = []
            if t == 1:
                ramp.append(u1[:])
            else:
                for k in range(t):
                    frac = k / (t - 1)
                    ramp.append([(1.0 - frac) * u0[i] + frac * u1[i] for i in range(6)])
            seq.append(ramp)
    if not seq:
        return []
    out: list[list[float]] = []
    for part in seq:
        out.extend(part)
    return out
